"""
Build and Execute 5 Complete 50-Cell Jupyter Notebooks (.ipynb) with Real Processing:
  00_data_representation_and_distribution_riyadh.ipynb (50 cells: 25 MD + 25 Code)
  01_feature_engineering_and_impact.ipynb            (50 cells: 25 MD + 25 Code)
  02_line_a_tabular_and_meta_models_riyadh.ipynb     (50 cells: 25 MD + 25 Code)
  03_line_b_pytorch_real_layers.ipynb                (50 cells: 25 MD + 25 Code)
  04_explainable_ai_xai_riyadh.ipynb                 (50 cells: 25 MD + 25 Code)

Split Protocol:
  - Train (70%) with 5-Fold Rolling-Origin Time-Series Cross-Validation (>=15d purge gap)
  - 15-Day Purge Gap
  - Validation (15%) for hyperparameter / early-stopping / Platt calibration tuning
  - 15-Day Purge Gap
  - Held-Out Test (15%)
Horizons: 1, 3, 7, 9, and 15-day forward averages ONLY.
Data: 06_Data/riyadh_line_a_tabular_features.csv (NO new external data added).
"""

import io
import os
import json
import base64
import contextlib
import warnings
from pathlib import Path

warnings.filterwarnings("ignore")

