        ("## 17. XAI-5: Real PyTorch LSTM Temporal Saliency (14-Day Lookback)",
         "torch.manual_seed(42); SEQ_LEN = 14\nX_all_s = pt.transform(imp.transform(df[feature_cols].values))\nX_tr_seq = torch.tensor(np.array([X_all_s[i-SEQ_LEN+1:i+1] for i in range(SEQ_LEN-1, tr_end)], dtype=np.float32))\ny_tr_seq = torch.tensor(df.iloc[SEQ_LEN-1:tr_end]['target_evt_any_7d'].values, dtype=torch.float32)\nX_te_seq = torch.tensor(np.array([X_all_s[i-SEQ_LEN+1:i+1] for i in range(te_start, N)], dtype=np.float32), requires_grad=True)\nclass MiniLSTM(nn.Module):\n    def __init__(self, d): super().__init__(); self.lstm = nn.LSTM(d, 32, batch_first=True); self.fc = nn.Linear(32, 1)\n    def forward(self, x): o, _ = self.lstm(x); return self.fc(o[:,-1,:]).squeeze(-1)\nm_l = MiniLSTM(len(feature_cols)); opt = torch.optim.Adam(m_l.parameters(), lr=2e-3); lf = nn.BCEWithLogitsLoss()\nfor _ in range(15): opt.zero_grad(); lf(m_l(X_tr_seq), y_tr_seq).backward(); opt.step()\nm_l.eval(); m_l(X_te_seq).sum().backward()\ntemp_sal = X_te_seq.grad.abs().mean(dim=(0, 2)).detach().numpy()\nfeat_sal = X_te_seq.grad.abs().mean(dim=(0, 1)).detach().numpy()\nprint('14-Day Temporal Saliency:', np.round(temp_sal, 4))"),
